        final int MOVES = n - 1;
        Node<E> temp = first;
        while (temp != null) {
            // move temp down n - 1 times if possible
            int count = 0;
            while (count < MOVES && temp != null) {
                temp = temp.next;
                count++;
            }
            if (temp != null) { // if temp IS null, not enough nodes
                if (temp.next != null) {
                     temp.next = temp.next.next;
                     numRemoved++;
                }
                else
                     // on last node, move temp to stop
