               int v1 = q1.dequeue();
               int v2 = q2.dequeue();
               if (v1 < v2) {
                    result.enqueue(v1);
                    result.enqueue(v2);
               } else {
                    result.enqueue(v2);
                    result.enqueue(v1);
               }
