     while (!s1.isEmpty() && !s2.isEmpty() && equal) {
          // OR !(s1.isEmpty() || s2.isEmpty()) && equal
          equal = s1.top().equals(s2.top());
          tempStack.push(s1.pop());
          tempStack.push(s2.pop());
     }

        // make sure both stacks are empty
        equal = equal && s1.isEmpty() && s2.isEmpty();

