           return true;
     } else {
           if (!n.isBlack) {
                // This is a red node. If children exist, they must be black.
                if (n.left != null && !n.left.isBlack) {
                      return false; // left child is red
                }
                if (n.right != null && !n.right.isBlack) {
                      return false; // right child is red
