    int numChunks = in.readBits(32);
    for (int chunk = 0; chunk < numChunks; chunk++) {
        int ones = 0;
        for (int bitIndex = 0; bitIndex < chunkSize; bitIndex++) {
            int bit = in.readBits(1);
            out.writeBits(1, bit);
            ones += bit;
        }
