     }

        for (int r = 0; r < cells.length; r++) {
            for (int c = 0; c <= r; c++) {
                if (cells[r][c] <= other.cells[r][c]) {
                    return false;
                }
            }
        }
        return true;
 }

private boolean square() {
       // recall, we know (assume) cells is rectangular
       return cells.length == cells[0].length;
}

